//! 自作整数解に目的上限制約を加えて既存Repairだけで改善を試す独立診断。
use mip_codex::{heuristic::Repair,model::{Model,Row},solve::Result};
use std::{fs::File,time::{Instant,Duration}};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m:Model=if a[1].ends_with(".json"){serde_json::from_reader(File::open(&a[1]).unwrap()).unwrap()}else{mip_codex::mps::read(&a[1]).unwrap()};assert!(!m.maximize&&m.offset==0.&&m.variables.iter().all(|v|v.integer&&v.lower==Some(0.)&&v.upper==Some(1.)&&v.objective.is_finite()&&v.objective>=0.));let seed:serde_json::Value=serde_json::from_reader(File::open(&a[2]).unwrap()).unwrap();let vals=&seed["values"];let mut x:Vec<_>=m.variables.iter().map(|v|vals[&v.name].as_f64().unwrap()).collect();assert!(Repair::new(&m).candidate_check(&x));let mut costs:Vec<_>=m.variables.iter().map(|v|v.objective).filter(|&c|c>0.).collect();assert!(!costs.is_empty());costs.sort_by(f64::total_cmp);let scale=costs[costs.len()/2];let step=costs[0];let start=Instant::now();let seconds:f64=a[3].parse().unwrap();let end=start+Duration::from_secs_f64(seconds);let mut records=Vec::new();let mut turn=0;
while Instant::now()<end{let mut work:Model=m.clone();let target=(m.objective(&x)-step)/scale;work.rows.push(Row{name:"diagnostic_objective_cut".into(),lower:None,upper:Some(target),coefficients:m.variables.iter().enumerate().filter(|(_,v)|v.objective!=0.).map(|(j,v)|(j,v.objective/scale)).collect(),exact_integral:false,exact_coefficients:false,exact_coefficient_flags:Vec::new(),lower_enclosure:None,upper_enclosure:Some([target,target])});let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let mut repair=Repair::new(&work);let deadline=end.min(Instant::now()+Duration::from_millis(500));let trial_point:Vec<_>=x.iter().map(|&v|if v>0.5{0.95}else{0.001}).collect();let trial=repair.search(&trial_point,&lower,&upper,deadline,100_000_000,turn);records.push(serde_json::json!({"target":target,"found":trial.is_some(),"work":repair.stats.work,"seconds":start.elapsed().as_secs_f64()}));if let Some(v)=trial{assert!(Repair::new(&m).candidate_check(&v));assert!(m.objective(&v)<m.objective(&x));x=v;}turn+=1;}
let r=Result{status:"feasible_objective_cut_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(&x).map(|(v,&x)|(v.name.clone(),x)).collect()),seconds:start.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(File::create(&a[4]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"objective":r.objective,"seconds":r.seconds,"records":records}));}
